const fs = require('fs');
const path = '/workspace/package.json';
const packageJson = JSON.parse(fs.readFileSync(path, 'utf8'));

// Function to set all values in an object to '0.0.1'
function setAllVersionsToZero(obj) {
  if (obj && typeof obj === 'object') {
    for (const key in obj) {
      if (typeof obj[key] === 'string' && obj[key].length > 0) {
        obj[key] = '0.0.1';
      }
    }
  }
}

// Update various dependency fields
setAllVersionsToZero(packageJson.dependencies);
setAllVersionsToZero(packageJson.devDependencies);
setAllVersionsToZero(packageJson.peerDependencies);
setAllVersionsToZero(packageJson.optionalDependencies);

// Write back to file
fs.writeFileSync(path, JSON.stringify(packageJson, null, 2));
console.log('Updated package.json with all dependency versions set to 0.0.1');
